// domain/ports/PaymentPort.ts  ("owned by the domain")
+import type Stripe from "stripe";
+
+export interface PaymentPort {
+  // leaks the vendor's request shape into the domain
+  charge(req: Stripe.PaymentIntentCreateParams): Promise<Stripe.PaymentIntent>;
+}

// domain/UpdateUserProfile.ts  (a plain CRUD update, no business rules)
+export class UpdateUserProfile {
+  constructor(private repo: UserRepositoryPort, private mapper: UserMapperPort) {}
+  async run(dto: UpdateUserDto) {
+    const entity = this.mapper.toEntity(dto);   // row in, row out — no invariants
+    await this.repo.save(entity);
+  }
+}
